        let empty_array: [Field; 0] = [];
        empty_array.for_each(|_x| assert(false));
    }

    #[test]
    fn for_eachi_empty() {
        let empty_array: [Field; 0] = [];
        empty_array.for_eachi(|_i, _x| assert(false));
    }

    #[test]
    fn map_example() {
        let a = [1, 2, 3];
        let b = a.map(|a| a * 2);
        assert_eq(b, [2, 4, 6]);
    }

    #[test]
    fn mapi_example() {
        let a = [1, 2, 3];
        let b = a.mapi(|i, a| i + a * 2);
        assert_eq(b, [2, 5, 8]);
    }

    #[test]
    fn for_each_example() {
        let a = [1, 2, 3];
        let mut b = [0, 0, 0];
        let b_ref = &mut b;
        let mut i = 0;
        let i_ref = &mut i;
        a.for_each(|x| {
            b_ref[*i_ref] = x * 2;
            *i_ref += 1;
        });
        assert_eq(b, [2, 4, 6]);
        assert_eq(i, 3);
    }

    #[test]
    fn for_eachi_example() {
        let a = [1, 2, 3];
        let mut b = [0, 0, 0];
        let b_ref = &mut b;
        a.for_eachi(|i, a| { b_ref[i] = i + a * 2; });
        assert_eq(b, [2, 5, 8]);
    }

    #[test]
    fn concat() {
        let arr1 = [1, 2, 3, 4];
        let arr2 = [6, 7, 8, 9, 10, 11];
        let concatenated_arr = arr1.concat(arr2);
        assert_eq(concatenated_arr, [1, 2, 3, 4, 6, 7, 8, 9, 10, 11]);
    }

    #[test]
    fn concat_zero_length_with_something() {
        let arr1 = [];
        let arr2 = [1];
        let concatenated_arr = arr1.concat(arr2);
        assert_eq(concatenated_arr, [1]);
    }

    #[test]
    fn concat_something_with_zero_length() {
        let arr1 = [1];
        let arr2 = [];
        let concatenated_arr = arr1.concat(arr2);
        assert_eq(concatenated_arr, [1]);
    }

    #[test]
    fn concat_zero_lengths() {
        let arr1: [Field; 0] = [];
        let arr2: [Field; 0] = [];
        let concatenated_arr = arr1.concat(arr2);
        assert_eq(concatenated_arr, []);
    }
}

